def create_default_calendar(apps, schema_editor):
    """
    The studio's default work calendar (decision Q20): a Monday to Friday, 8 hour week in UTC.
    Resources with no calendar of their own follow it. Not in the model state, so written by hand.
    """
    WorkCalendar = apps.get_model("scheduling", "WorkCalendar")
    if WorkCalendar._base_manager.filter(is_default=True, is_deleted=False).exists():
        return
    WorkCalendar._base_manager.get_or_create(
        code="STUDIO",
        defaults={
            "name": "Studio",
            "time_zone": "UTC",
            "working_weekdays": [1, 2, 3, 4, 5],
            "hours_per_day": 8,
            "is_default": True,
        },
    )


